import java.util.concurrent.ExecutionException;
import java.util.concurrent.ScheduledExecutorService;
import java.util.stream.Collectors;
import java.util.stream.StreamSupport;

import static org.assertj.core.api.Assertions.assertThat;

public class RootExceptionHistoryEntryTest extends TestLogger {

    @ClassRule
    public static final TestExecutorResource<ScheduledExecutorService> EXECUTOR_RESOURCE =
        TestingUtils.defaultExecutorResource();

    private ExecutionGraph executionGraph;

    @Before
    public void setup() throws JobException, JobExecutionException {
        final JobGraph jobGraph = JobGraphTestUtils.singleNoOpJobGraph();
        jobGraph.getVertices().forEach(v -> v.setParallelism(3));

        executionGraph = 
            TestingDefaultExecutionGraphBuilder.newBuilder()
                .setJobGraph(jobGraph)
                .build(EXECUTOR_RESOURCE.getExecutor());
        executionGraph.start(ComponentMainThreadExecutorServiceAdapter.forMainThread());
    }

    @Test
    public void testFromFailureHandlingResultSnapshot() throws ExecutionException, InterruptedException {
        final Throwable rootException = new RuntimeException("Expected root failure");
        final ExecutionVertex rootExecutionVertex = extractExecutionVertex(0);
        final long rootTimestamp = triggerFailure(rootExecutionVertex, rootException);
        final CompletableFuture<Map<String, String>> rootFailureLabels =
            CompletableFuture.completedFuture(Collections.singletonMap("key", "value"));

        final Throwable concurrentException = new IllegalStateException("Expected other failure");
        final ExecutionVertex concurrentlyFailedExecutionVertex = extractExecutionVertex(1);
        final long concurrentExceptionTimestamp = triggerFailure(concurrentlyFailedExecutionVertex, concurrentException);

        final FailureHandlingResultSnapshot snapshot =
            new FailureHandlingResultSnapshot(
                rootExecutionVertex.getCurrentExecutionAttempt(),
                rootException,
                rootTimestamp,
                rootFailureLabels,
                Collections.singleton(concurrentlyFailedExecutionVertex.getCurrentExecutionAttempt()));

        final RootExceptionHistoryEntry actualEntry =
            RootExceptionHistoryEntry.fromFailureHandlingResultSnapshot(snapshot);

        assertThat(actualEntry).isEqualTo(ExceptionHistoryEntryMatcher.matchesFailure(
                rootException,
                rootTimestamp,
                rootFailureLabels.get(),
                rootExecutionVertex.getTaskNameWithSubtaskIndex(), 
                rootExecutionVertex.getCurrentAssignedResourceLocation()));

        assertThat(actualEntry.getConcurrentExceptions()).containsExactly(
                ExceptionHistoryEntryMatcher.matchesFailure(
                    concurrentException,
                    concurrentExceptionTimestamp,
                    concurrentlyFailedExecutionVertex.getTaskNameWithSubtaskIndex(),
                    concurrentlyFailedExecutionVertex.getCurrentAssignedResourceLocation()));
    }

    @Test
    public void testFromGlobalFailure() throws ExecutionException, InterruptedException {
        final Throwable concurrentException0 =
            new RuntimeException("Expected concurrent failure #0");
        final ExecutionVertex concurrentlyFailedExecutionVertex0 = extractExecutionVertex(0);
        final long concurrentExceptionTimestamp0 = triggerFailure(concurrentlyFailedExecutionVertex0, concurrentException0);

        final Throwable concurrentException1 =
            new IllegalStateException("Expected concurrent failure #1");
        final ExecutionVertex concurrentlyFailedExecutionVertex1 = extractExecutionVertex(1);
        final long concurrentExceptionTimestamp1 = triggerFailure(concurrentlyFailedExecutionVertex1, concurrentException1);

        final Throwable rootCause = new Exception("Expected root failure");
        final long rootTimestamp = System.currentTimeMillis();
        final CompletableFuture<Map<String, String>> rootFailureLabels =
                CompletableFuture.completedFuture(Collections.singletonMap("key", "value"));

        final RootExceptionHistoryEntry actualEntry =
            RootExceptionHistoryEntry.fromGlobalFailure(
                rootCause,
                rootTimestamp,
                rootFailureLabels,
                StreamSupport.stream(executionGraph.getAllExecutionVertices().spliterator(), false)
                    .map(ExecutionVertex::getCurrentExecutionAttempt)
                    .collect(Collectors.toSet()));

        assertThat(actualEntry).isEqualTo(ExceptionHistoryEntryMatcher.matchesGlobalFailure(
                rootCause, rootTimestamp, rootFailureLabels.get()));
        assertThat(actualEntry.getConcurrentExceptions()).containsExactlyInAnyOrder(
                ExceptionHistoryEntryMatcher.matchesFailure(
                    concurrentException0, concurrentExceptionTimestamp0, 
                    concurrentlyFailedExecutionVertex0.getTaskNameWithSubtaskIndex(), 
                    concurrentlyFailedExecutionVertex0.getCurrentAssignedResourceLocation()),
                ExceptionHistoryEntryMatcher.matchesFailure(
                    concurrentException1, concurrentExceptionTimestamp1, 
                    concurrentlyFailedExecutionVertex1.getTaskNameWithSubtaskIndex(), 
                    concurrentlyFailedExecutionVertex1.getCurrentAssignedResourceLocation()));
    }

    private long triggerFailure(ExecutionVertex executionVertex, Throwable throwable) {
        executionGraph.updateState(new TaskExecutionStateTransition(
                new TaskExecutionState(
                        executionVertex.getCurrentExecutionAttempt().getAttemptId(),
                        ExecutionState.FAILED,
                        throwable)));

        return executionVertex.getFailureInfo().orElseThrow(() -> 
            new IllegalArgumentException("The transition into failed state didn't succeed for ExecutionVertex " + 
            executionVertex.getID() + "."))
            .getTimestamp();
    }

    private ExecutionVertex extractExecutionVertex(int pos) {
        final ExecutionVertex executionVertex = Iterables.get(executionGraph.getAllExecutionVertices(), pos);
        executionVertex.tryAssignResource(new TestingLogicalSlotBuilder().createTestingLogicalSlot());
        return executionVertex;
    }
}
