     * @param maxNumberOfParallelSubtasks Maximum number of parallel subtasks (must be positive).
     * @param indexOfSubtask Index of this subtask (>= 0).
     * @param numberOfParallelSubtasks Number of parallel subtasks (must be positive).
     * @param attemptNumber Attempt number for this task (must be non-negative).
     */
    public TaskInfo(String taskName, int maxNumberOfParallelSubtasks, int indexOfSubtask, 
                    int numberOfParallelSubtasks, int attemptNumber) {
        this(taskName, maxNumberOfParallelSubtasks, indexOfSubtask, numberOfParallelSubtasks,
             attemptNumber, "UNKNOWN");
    }

    public TaskInfo(String taskName, int maxNumberOfParallelSubtasks, int indexOfSubtask, 
                    int numberOfParallelSubtasks, int attemptNumber, String allocationIDAsString) {

        Preconditions.checkArgument(indexOfSubtask >= 0, "Index of subtask must be non-negative.");
        Preconditions.checkArgument(maxNumberOfParallelSubtasks > 0, "Max parallelism must be positive.");
        Preconditions.checkArgument(maxNumberOfParallelSubtasks >= numberOfParallelSubtasks,
                                    "Max parallelism must be >= number of parallel subtasks.");
        Preconditions.checkArgument(numberOfParallelSubtasks > 0, "Number of parallel subtasks must be positive.");
        Preconditions.checkArgument(indexOfSubtask < numberOfParallelSubtasks, 
                                    "Index of subtask must be less than the number of parallel subtasks.");
        Preconditions.checkArgument(attemptNumber >= 0, "Attempt number must be non-negative.");

        this.taskName = Preconditions.checkNotNull(taskName, "Task name must not be null.");
        this.maxNumberOfParallelSubtasks = maxNumberOfParallelSubtasks;
        this.indexOfSubtask = indexOfSubtask;
        this.numberOfParallelSubtasks = numberOfParallelSubtasks;
        this.attemptNumber = attemptNumber;
        this.allocationIDAsString = Preconditions.checkNotNull(allocationIDAsString);

        this.taskNameWithSubtasks = formatTaskNameWithSubtasks();
    }

    private String formatTaskNameWithSubtasks() {
        return String.format("%s (%d/%d)#%d", taskName, indexOfSubtask + 1, numberOfParallelSubtasks, attemptNumber);
    }

